mapper.sql:
SELECT selected.id
FROM (
    SELECT id
    FROM app_generation_task
    WHERE COALESCE(finished_at, started_at, queued_at) < #{cutoff}
      AND status IN ('SUCCESS', 'FAILED', 'STOPPED')
    ORDER BY id
    LIMIT #{batchSize}
) selected

SELECT selected.id
FROM (
    SELECT a.id
    FROM app_generation_attempt a
    WHERE a.started_at < #{cutoff}
      AND (a.generation_task_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM app_generation_task t WHERE t.id = a.generation_task_id
      ))
    ORDER BY a.id
    LIMIT #{batchSize}
) selected

SELECT selected.id
FROM (
    SELECT e.id
    FROM app_generation_stat_event e
    WHERE e.created_at < #{cutoff}
      AND (e.task_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM app_generation_task t WHERE t.id = e.task_id
      ))
    ORDER BY e.id
    LIMIT #{batchSize}
) selected
